def check_sum_condition(n):
    # The necessary condition is that n(3n+1) must be divisible by 4.
    numerator = n * (3 * n + 1)
    return numerator % 4 == 0

n_values = [99, 100, 205, 206]
results = {}
for n in n_values:
    is_solvable = check_sum_condition(n)
    results[n] = is_solvable

print(results)

def find_m_M(start, end):
    # Find smallest m >= start such that m % 4 in {0, 1}
    m = start
    while m <= end and m % 4 not in [0, 1]:
        m += 1

    # Find largest M <= end such that M % 4 in {0, 1}
    M = end
    while M >= start and M % 4 not in [0, 1]:
        M -= 1

    return m, M

start_range = 99
end_range = 206
m, M = find_m_M(start_range, end_range)
print(f"m = {m}")
print(f"M = {M}")
print(f"m + M = {m + M}")
